suspend fun route(input: ReceiveChannel<Envelope>, out: Map<RouteKey, SendChannel<Envelope>>) {
    for (msg in input) {                       // ends when upstream closes
        val key = when (val body = msg.body) { // exhaustive over the sealed hierarchy
            is Order.Created -> RouteKey.PAYMENT
            is Order.Shipped -> RouteKey.FULFILMENT
        }
        out.getValue(key).send(msg)            // unmodified; suspends = backpressure
    }
}
